"""Simulated IoD intrusion dataset (``D2D-SIM``), generated by our simulator.

Every run is a full simulation of a D2DAP-secured swarm (System A) with at most one
attack. Runs are randomised along several axes so that the classifier cannot learn a
single fixed pattern: attack kind, intensity (packets/s), target drone, start time and
duration, swarm size, and benign traffic mix (including "hard negative" benign runs with
heavy video bursts). Each window-level sample keeps its ``run_id`` so train/test splits
can be made *by run* (no temporal leakage between adjacent windows of the same run).

THIS IS SIMULATED DATA. Accuracy on it says nothing about real drone networks.
"""

from __future__ import annotations

from collections.abc import Callable
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass

import numpy as np
import pandas as pd

from app.attacks.manager import TRAFFIC_ATTACKS
from app.core.rng import RandomStreams
from app.experiments.scenario import (
    ScenarioConfig,
    Variant,
    run_attack_scenario,
    run_benign_scenario,
)
from app.ids.features import extract_windows
from app.models.enums import BENIGN_LABEL
from app.services.swarm import SecureSwarm
from app.simulation.traffic import TrafficConfig

META_COLUMNS = ("run_id", "seed", "scenario_kind", "rate_pps", "num_drones", "target",
                "attack_start_ms", "attack_end_ms")  # fmt: skip


@dataclass(frozen=True)
class DatasetConfig:
    """What to simulate."""

    seeds: tuple[int, ...] = (101, 102, 103, 104)
    kinds: tuple[str, ...] = TRAFFIC_ATTACKS
    rates_pps: tuple[float, ...] = (3.0, 10.0, 30.0)
    benign_runs_per_seed: int = 4
    duration_ms: int = 45_000
    drone_counts: tuple[int, ...] = (8, 10, 12)

    @classmethod
    def quick(cls) -> DatasetConfig:
        return cls(seeds=(101, 102), rates_pps=(10.0,), benign_runs_per_seed=2,
                   duration_ms=25_000, drone_counts=(6, 8))  # fmt: skip


def _roles(swarm: SecureSwarm) -> dict[str, str]:
    return {i: d.role.value for i, d in swarm.engine.network.nodes.items()}


def _scenario(rng: np.random.Generator, cfg: DatasetConfig, rate: float, hard: bool
              ) -> ScenarioConfig:  # fmt: skip
    n = int(rng.choice(cfg.drone_counts))
    start = int(rng.integers(6_000, max(7_000, cfg.duration_ms // 3)))
    dur = int(rng.integers(cfg.duration_ms // 4, cfg.duration_ms - start - 2_000))
    traffic = TrafficConfig(
        video_fraction=1.0 if hard else float(rng.uniform(0.2, 0.7)),
        video_rate_pps=float(rng.uniform(35, 60)) if hard else float(rng.uniform(15, 35)),
        telemetry_interval_ms=int(rng.integers(150, 300)),
    )
    return ScenarioConfig(
        num_drones=n,
        duration_ms=cfg.duration_ms,
        attack_start_ms=start,
        attack_duration_ms=max(3_000, dur),
        rate_pps=rate,
        target=f"D{int(rng.integers(2, n + 1))}",
        traffic=traffic,
    )


@dataclass(frozen=True)
class _RunJob:
    run_id: int
    seed: int
    kind: str
    rate: float
    scenario: ScenarioConfig
    params: tuple[tuple[str, str], ...]


def _plan(cfg: DatasetConfig, base_seed: int) -> list[_RunJob]:
    """Draw every run's randomised parameters up front (deterministic, order-independent)."""
    plan_rng = RandomStreams(base_seed).numpy("dataset-plan")
    jobs: list[_RunJob] = []
    run_id = 0
    for seed in cfg.seeds:
        specs: list[tuple[str, float, bool]] = [
            (k, r, False) for k in cfg.kinds for r in cfg.rates_pps
        ]
        specs += [(BENIGN_LABEL, 0.0, i % 2 == 1) for i in range(cfg.benign_runs_per_seed)]
        for kind, rate, hard in specs:
            run_id += 1
            sc = _scenario(plan_rng, cfg, rate, hard)
            params = (
                (("window", str(plan_rng.choice(["in", "stale"]))),) if kind == "replay" else ()
            )
            jobs.append(_RunJob(run_id, seed, kind, rate, sc, params))
    return jobs


def _simulate(job: _RunJob) -> pd.DataFrame:
    """One simulation run -> window samples (executed in a worker process)."""
    run_seed = job.seed * 1000 + job.run_id
    sc, kind = job.scenario, job.kind
    if kind == BENIGN_LABEL:
        swarm = run_benign_scenario(Variant.D2DAP, sc, run_seed).swarm
    else:
        swarm = run_attack_scenario(Variant.D2DAP, kind, sc, run_seed, dict(job.params)).swarm
    win = extract_windows(swarm.traffic_log.to_frame(), _roles(swarm))
    # Every claimed source is kept, including unknown ids (e.g. rogue drones): a monitor
    # tracks whatever source address appears on the channel.
    attack = kind != BENIGN_LABEL
    return win.assign(
        run_id=job.run_id, seed=job.seed, scenario_kind=kind, rate_pps=job.rate,
        num_drones=sc.num_drones, target=sc.target if attack else "",
        attack_start_ms=sc.attack_start_ms if attack else -1,
        attack_end_ms=sc.attack_start_ms + sc.attack_duration_ms if attack else -1,
    )  # fmt: skip


def generate(
    cfg: DatasetConfig,
    base_seed: int = 0,
    progress: Callable[[str], None] | None = None,
    workers: int = 1,
) -> pd.DataFrame:
    """Simulate all runs (optionally in parallel) and return window-level samples."""
    jobs = _plan(cfg, base_seed)
    if workers > 1:
        with ProcessPoolExecutor(max_workers=workers) as pool:
            frames = list(pool.map(_simulate, jobs, chunksize=1))
    else:
        frames = [_simulate(j) for j in jobs]
    if progress is not None:
        progress(f"simulated {len(jobs)} runs, {sum(len(f) for f in frames)} windows")
    return pd.concat(frames, ignore_index=True).sort_values(["run_id", "window", "src"],
                                                             ignore_index=True)  # fmt: skip
